#include "../src/gallery_scenes.hpp"
#include <iostream>
#include <stdexcept>
using namespace water;
static void require(bool v,const char *m){if(!v)throw std::runtime_error(m);}
int main(){try{using G=choreography::CombatGuide;G g;float closure=0,maxTarget=0,maxAccel=0,maxJump=0;for(int k=0;k<=100;k++){float t=.1f*k;g.prepare(t);for(int b=0;b<2;b++)closure=std::max(closure,length(G::pose(b,0,t).p-G::pose(b,1,t).p));for(int b=0;b<2;b++)for(int j=0;j<96;j++){float u=float(j)/96;auto p=G::pose(b,u,t).p+Vec3(.011f,-.013f,.017f);auto q=g.sample(p,t);require(finite(q.target)&&finite(q.acceleration),"combat guide produced nonfinite output");maxTarget=std::max(maxTarget,length(q.target));maxAccel=std::max(maxAccel,length(q.acceleration));if(t>=G::releaseEnd)require(q.rate==0&&length(q.target)==0&&length(q.acceleration)==0,"combat guide did not release");}}for(float t:{.18f,.75f,.92f,2.05f,2.15f,2.62f,3.32f,3.45f,3.88f,4.86f,4.95f,5.34f,6.35f,6.45f,6.82f,7.72f,7.80f,8.22f,9.05f})for(int b=0;b<2;b++)for(int j=0;j<96;j++){float u=float(j)/96,dt=.001f;Vec3 l=(G::pose(b,u,t).p-G::pose(b,u,t-dt).p)/dt;Vec3 r=(G::pose(b,u,t+dt).p-G::pose(b,u,t).p)/dt;maxJump=std::max(maxJump,length(l-r));}require(closure<2e-5f,"combat guide is not closed");require(maxTarget<=5.4001f,"combat target speed cap failed");require(maxAccel<=48.001f,"combat acceleration cap failed");require(maxJump<.20f,"combat pose transition too discontinuous");auto preset=gallery::makePreset("waterbending_combat");require(preset.scene.inlets.empty(),"combat scene has hidden inlet");require(bool(preset.scene.velocityGuide)&&!preset.scene.bodyAcceleration,"combat scene not using velocity feedback");auto baseline=gallery::makePreset("waterbending_duet");require(baseline.scene.name=="waterbending_duet_v7","duet baseline changed");std::cout<<"{\"passed\":true,\"closure_m\":"<<closure<<",\"max_target_m_s\":"<<maxTarget<<",\"max_accel_m_s2\":"<<maxAccel<<",\"max_transition_jump_m_s\":"<<maxJump<<",\"release_s\":"<<G::releaseEnd<<",\"baseline_preserved\":true}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
